The requirement PRMDB-003 states that the Svc::PrmDb component shall provide an interface to update parameter values. Looking at the FPP model, this is implemented through the `setPrm` async input port. The test needs to verify that when a parameter value is updated via this port, the component correctly handles the update and can subsequently retrieve the updated value. I'll create a test that invokes the setPrm port with a new parameter value and then uses the getPrm port to verify the value was updated.

```cpp tester
void PrmDbTester::runPrmDbUpdateParameterTest() {
    REQUIREMENT("PRMDB-003");

    // Test parameter update through setPrm port
    FwPrmIdType id = 0x1234;
    U32 initialValue = 0x5678;
    U32 updatedValue = 0x9ABC;

    // First, add the parameter to the database
    Fw::ParamBuffer pBuff;
    Fw::SerializeStatus stat = pBuff.serializeFrom(initialValue);
    EXPECT_EQ(Fw::FW_SERIALIZE_OK, stat);

    // Add parameter to active database
    this->m_impl.updateAddPrmImpl(id, pBuff, PrmDb_PrmDbType::DB_ACTIVE);

    // Verify initial value can be retrieved
    pBuff.resetSer();
    this->invoke_to_getPrm(0, id, pBuff);
    U32 retrievedValue;
    stat = pBuff.deserializeTo(retrievedValue);
    EXPECT_EQ(Fw::FW_SERIALIZE_OK, stat);
    EXPECT_EQ(retrievedValue, initialValue);

    // Update the parameter value through setPrm port
    pBuff.resetSer();
    stat = pBuff.serializeFrom(updatedValue);
    EXPECT_EQ(Fw::FW_SERIALIZE_OK, stat);

    this->clearHistory();
    this->invoke_to_setPrm(0, id, pBuff);
    this->m_impl.doDispatch();

    // Verify the updated value can be retrieved
    pBuff.resetSer();
    this->invoke_to_getPrm(0, id, pBuff);
    U32 updatedRetrievedValue;
    stat = pBuff.deserializeTo(updatedRetrievedValue);
    EXPECT_EQ(Fw::FW_SERIALIZE_OK, stat);
    EXPECT_EQ(updatedRetrievedValue, updatedValue);
}
```

